$root=__DIR__; $prepared=[]; $original=[]; $marker='/* IDEARE room openings and exact dimensions */';
function failInstall($s){fwrite(STDERR,$s.PHP_EOL);exit(1);}
foreach($manifest as $relative=>$spec){
 $path=$root.DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$relative);
 if(!is_file($path))failInstall('Missing file: '.$relative.' - no changes made.');
 $source=file_get_contents($path);if($source===false)failInstall('Cannot read '.$relative);
 // Git may check out CRLF on Windows; compare the LF-normalized Git blob too.
 $lf=str_replace("\r\n","\n",$source);
 $gitHash=static fn($s)=>sha1('blob '.strlen($s)."\0".$s);
 if($gitHash($source)===$spec['sha'])$base=$source;
 elseif($gitHash($lf)===$spec['sha'])$base=$lf;
 else failInstall('Version mismatch: '.$relative.' - no files changed. Use the reviewed GitHub revision or keep your local version.');
 $out=str_replace("\r\n","\n",$base);
 foreach($spec['patches']??[] as [$before,$after,$expected]){
  if(substr_count($out,$before)!==$expected)failInstall('Patch anchor mismatch in '.$relative.' - no files changed.');
  $out=str_replace($before,$after,$out);
 }
 $out.=$spec['append']??'';
 if(str_contains($source,"\r\n"))$out=str_replace("\n","\r\n",$out);
 $original[$path]=$source;$prepared[$path]=$out;
}
$backup=dirname($root).DIRECTORY_SEPARATOR.'IDEARE-door-backup-'.date('Ymd-His').'-'.bin2hex(random_bytes(3));
if(!mkdir($backup,0700,true))failInstall('Cannot create backup.');
$staged=[];
foreach($prepared as $path=>$out){
 $relative=substr($path,strlen($root)+1);$dest=$backup.DIRECTORY_SEPARATOR.$relative;
 if(!is_dir(dirname($dest))&&!mkdir(dirname($dest),0700,true))failInstall('Cannot create backup directory.');
 if(file_put_contents($dest,$original[$path])!==strlen($original[$path]))failInstall('Backup failed: '.$relative);
 $tmp=tempnam(dirname($path),'id3door-');if($tmp===false||file_put_contents($tmp,$out)!==strlen($out))failInstall('Cannot stage '.$relative);
 $staged[$path]=$tmp;
 if(str_ends_with($path,'.php')){exec(escapeshellarg(PHP_BINARY).' -l '.escapeshellarg($tmp),$lint,$rc);if($rc!==0){foreach($staged as $t)@unlink($t);failInstall('PHP lint failed: '.implode(' ',$lint));}}
}
$written=[];try{foreach($staged as $path=>$tmp){if(file_put_contents($path,$prepared[$path],LOCK_EX)!==strlen($prepared[$path]))throw new RuntimeException('Write failed: '.$path);$written[]=$path;}}
catch(Throwable $e){foreach($original as $path=>$bytes)file_put_contents($path,$bytes,LOCK_EX);foreach($staged as $tmp)@unlink($tmp);failInstall($e->getMessage().' - attempted restore; backup: '.$backup);}
foreach($staged as $tmp)@unlink($tmp);
echo 'Door and room measurement update installed.'.PHP_EOL.'Backup: '.$backup.PHP_EOL.'Refresh the designer (Ctrl+Shift+R).'.PHP_EOL;
